head.script:
scwin.screenId = "jldstf30012";

///////// 1. 변수 및 선언 영역 /////////

scwin.btn_VIEWDSCL = $c.util.getComponent('btn_VIEWDSCL');

scwin.txa_REMK = $c.util.getComponent('txa_REMK');

scwin.Grd_com_isur = $c.util.getComponent('Grd_com_isur');

scwin.gParamObj = undefined;

scwin.inputType = "C";

scwin.vScrenID = 'ULDSTF30012.gfm';

scwin.vSecugrpID = "SCH";

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.inputType = undefined;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.resizeToWin();
        scwin.fn_Init();
        scwin.getParam();
        fn_com_isur(ipt_txb_ISUR_CD, ipt_txb_COM_NM);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_Schedule = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Schedule')) : $c.util.getComponent('dts_Schedule');

scwin.dts_Charge2_Info = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Charge2_Info')) : $c.util.getComponent('dts_Charge2_Info');

scwin.dts_Status = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Status')) : $c.util.getComponent('dts_Status');

scwin.MxDataSet_com_isur = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('MxDataSetComIsur')) : $c.util.getComponent('MxDataSetComIsur');

scwin.gDepCd = undefined; try { scwin.gDepCd = /* sdd-asis-lifecycle:begin gDepCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("depCd")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30012' }); }

scwin.gEmpNo = undefined; try { scwin.gEmpNo = /* sdd-asis-lifecycle:begin gEmpNo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("empNo")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30012' }); }

scwin.gLdMktTp = undefined; try { scwin.gLdMktTp = /* sdd-asis-lifecycle:begin gLdMktTp — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("market")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30012' }); }

scwin.gMarket = undefined; try { scwin.gMarket = /* sdd-asis-lifecycle:begin gMarket — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("market")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30012' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf30012.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Close_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Close_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Close_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.frame.CloseFrame();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.btn_Close_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Save_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Save_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.fn_Save();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.btn_Save_onclick' }); }
};

/**
 * @method
 * @name scwin.trs_Save_onfail
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.trs_Save_onfail = function () {
    /* sdd-asis-lifecycle:begin trs_Save_onfail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.fil.alert_error(trs_Save);
    scwin.dts_Schedule.removeAll();
    (scwin.dts_Schedule.insertRow(), scwin.dts_Schedule.setRowPosition(scwin.dts_Schedule.getRowCount()-1));
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.trs_Save_onsuccess
 * @author Inswave
 * @date 2026. 09. 29
 * @description 알림을 띄운다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.trs_Save_onsuccess = async function () {
    /* sdd-asis-lifecycle:begin trs_Save_onsuccess — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert($c.data.getMessage("MSG-A001", "저장"));
    const fr_fn_SearchMain = $c.frame.Provider("../").fn_SearchMain;
    if (fr_fn_SearchMain == null) {
        const parentWin = $c.frame.Provider("../");
        const parendID = $c.util.getParameter($c.frame.srcUrl, "frameid");
        const fr_fn_Search = parentWin.Provider(parendID).fn_Search;
        fr_fn_Search();
        $c.frame.CloseFrame();
    } else {
        fr_fn_SearchMain();
        $c.frame.CloseFrame();
    }
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.dts_Schedule_onloadcompleted
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowcount
 * @returns
 * @hidden N
*/
scwin.dts_Schedule_onloadcompleted = function (rowcount) {
    /* sdd-asis-lifecycle:begin dts_Schedule_onloadcompleted — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const vISUR_CD = scwin.dts_Schedule.getCellData(1, "ISUR_CD");
    const vLD_MKT_TP_CD = scwin.dts_Schedule.getCellData(1, "LD_MKT_TP_CD");
    if (vISUR_CD !== '' && vISUR_CD.length == 5) {
        scwin.fn_ReadChrgInfo(vISUR_CD, vLD_MKT_TP_CD);
    }
    /* sdd-asis-lifecycle:end */
};

/**
 * @event
 * @name scwin.btn_ISUR_CD_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_ISUR_CD_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_ISUR_CD_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if ($c.session.getUserInfo("bondYn") === 'Y') {
            IsurcdSearchBond(ipt_txb_ISUR_CD, ipt_txb_COM_NM);
        } else {
            if ($c.fil.getObjectValue(rd_rdo_SCHDL_TP_CD) === '6') {
                fn_GetPar = scwin.getParIsuCd;
                fn_SetPar = scwin.setParIsuCd;
                $c.lc.fn_PopFindIsu(scwin.vSecugrpID);
            } else {
                IsurcdSearch(ipt_txb_ISUR_CD, ipt_txb_COM_NM);
            }
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.btn_ISUR_CD_onclick' }); }
};

/**
 * @event
 * @name scwin.Grd_com_isur_onkeypress
 * @author Inswave
 * @date 2026. 09. 29
 * @param kcode
 * @returns
 * @hidden N
*/
scwin.Grd_com_isur_onkeypress = function (kcode) {
    try {
        /* sdd-asis-lifecycle:begin Grd_com_isur_onkeypress — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if (kcode === '13') {
            fn_com_Confirm_set();
            scwin.readChrgInfo2();
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.Grd_com_isur_onkeypress' }); }
};

/**
 * @event
 * @name scwin.Grd_com_isur_ondblclick
