*/
scwin.Grd_com_isur_ondblclick = function (row, colid) {
    try {
        /* sdd-asis-lifecycle:begin Grd_com_isur_ondblclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_com_Confirm_set();
        scwin.readChrgInfo2();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.Grd_com_isur_ondblclick' }); }
};

/**
 * @event
 * @name scwin.Grd_com_isur_onclick
