 * @date 2026. 09. 29
 * @description Grd_com_isur 의 onclick 에서 Grd_com_isur 을(를) 보이기를 바꾼다
 * @param row colid
 * @returns
 * @hidden N
*/
scwin.Grd_com_isur_onclick = function (row, colid) {
    try {
        /* sdd-asis-lifecycle:begin Grd_com_isur_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.Grd_com_isur.setStyle("display", "");
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.Grd_com_isur_onclick' }); }
};

/**
 * @event
 * @name scwin.Grd_com_isur_onsetfocus
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.Grd_com_isur_onsetfocus = function () {
    try {
        /* sdd-asis-lifecycle:begin Grd_com_isur_onsetfocus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        stFocusGrid = true;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.Grd_com_isur_onsetfocus' }); }
};

/**
 * @event
 * @name scwin.Grd_com_isur_onkillfocus
 * @author Inswave
 * @date 2026. 09. 29
 * @description Grd_com_isur 을(를) 보이기를 바꾼다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.Grd_com_isur_onkillfocus = function () {
    try {
        /* sdd-asis-lifecycle:begin Grd_com_isur_onkillfocus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        stFocusGrid = false;
        scwin.Grd_com_isur.setStyle("display", "none");
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.Grd_com_isur_onkillfocus' }); }
};

/**
 * @event
 * @name scwin.txb_ISUR_CD_onblur
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.txb_ISUR_CD_onblur = function () {
    try {
        /* sdd-asis-lifecycle:begin txb_ISUR_CD_onblur — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if (stFocusGrid === false) {
            scwin.Grd_com_isur.setStyle("display", "none");
        }
        if (ipt_txb_ISUR_CD.value === "") {
            $c.util.getComponent("ipt_txb_COM_NM").setValue("");
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.txb_ISUR_CD_onblur' }); }
};

/**
 * @event
 * @name scwin.txb_ISUR_CD_onfocus
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.txb_ISUR_CD_onfocus = function () {
    try {
        /* sdd-asis-lifecycle:begin txb_ISUR_CD_onfocus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if (ipt_txb_ISUR_CD.readOnly === false) {
            scwin.Grd_com_isur.setStyle("display", "none");
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.txb_ISUR_CD_onfocus' }); }
};

/**
 * @event
 * @name scwin.txb_ISUR_CD_onkeyup
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.txb_ISUR_CD_onkeyup = function () {
    try {
        /* sdd-asis-lifecycle:begin txb_ISUR_CD_onkeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if (ipt_txb_ISUR_CD.value === "") {
            scwin.Grd_com_isur.setStyle("display", "none");
        } else {
            if ($c.util.getKeyCode(event) == 40) {
                scwin.Grd_com_isur.Focus();
            } else {
                fn_com_isur_nm($c.util.getKeyCode(event));
            }
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.txb_ISUR_CD_onkeyup' }); }
};

/**
 * @method
 * @name scwin.MxDataSet_com_isur_onfilter
 * @author Inswave
 * @date 2026. 09. 29
 * @param row
 * @returns
 * @hidden N
*/
scwin.MxDataSet_com_isur_onfilter = function (row) {
    /* sdd-asis-lifecycle:begin MxDataSet_com_isur_onfilter — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (skw !== "" && foColum === "1") {
        f1 = scwin.MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = scwin.MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) {
            return true;
        } else {
            return false;
        }
    } else {
        return true;
    }
    /* sdd-asis-lifecycle:end */
};

/**
 * @event
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Delete_onclick = async function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Delete_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fn_Delete();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30012.btn_Delete_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_VIEWDSCL_onclick
 * @author Inswave
 * @date 2026. 09. 29
