 * @returns
 * @hidden N
*/
scwin.btn_VIEWDSCL_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_VIEWDSCL_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const AcptNo = scwin.dts_Schedule.getCellData(1, "ACPT_NO");
        if (AcptNo !== '') {
            $c.fil.fn_OpenDisclViewer(AcptNo, "R");
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.btn_VIEWDSCL_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Search_Rpt_Nm_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Search_Rpt_Nm_onclick = async function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Search_Rpt_Nm_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.openDiscls();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30012.btn_Search_Rpt_Nm_onclick' }); }
};

/**
 * @event
 * @name scwin.rdo_SCHDL_TP_CD_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.rdo_SCHDL_TP_CD_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin rdo_SCHDL_TP_CD_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.fil.setObjectValue(ipt_txb_ISUR_CD, "");
        $c.fil.setObjectValue(ipt_txb_COM_NM, "");
        if ($c.fil.getObjectValue(rd_rdo_SCHDL_TP_CD) === '5') {
            $c.util.getComponent('ipt_txb_ISUR_CD').setReadOnly(false);
        } else {
            $c.util.getComponent('ipt_txb_ISUR_CD').setReadOnly(true);
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.rdo_SCHDL_TP_CD_onclick' }); }
};

/**
 * @event
 * @name scwin.txa_REMK_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.txa_REMK_onchange = function () {
    try {
        /* sdd-asis-lifecycle:begin txa_REMK_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.fil.setObjectValue(ipt_txbTitleSize, $c.str.getByteLength($c.fil.getObjectValue(scwin.txa_REMK)));
        if ($c.str.getByteLength($c.fil.getObjectValue(scwin.txa_REMK)) > 1500) {
            $c.fil.setObjectValue(ipt_txbAlert, '가 초과되었습니다.');
            scwin.txa_REMK.Focus();
            return;
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30012.txa_REMK_onchange' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_script_dts_Status
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_dts_Status = async function () {
    $c.util.getComponent("dma_scriptDts_StatusReq").set("inputMessageId", "CODEVALUE_INOUT");
    $c.util.getComponent("dma_scriptDts_StatusReq").set("outputMessageId", "CODE_OUT");
    $c.util.getComponent("dma_scriptDts_StatusReq").set("FOR", "C");
    $c.util.getComponent("dma_scriptDts_StatusReq").set("CD_ENG_NM", "DISCLS_SCHDL_ACT_STAT_CD");
    const sbmOptions = {
        id: "tx_script_dts_Status",
        method: "post",
        action: "/CodeAction.do",
        ref: "dma_scriptDts_StatusReq",
        target: "dts_Status=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_Status_onloaderror'] === 'function') ? scwin['dts_Status_onloaderror'] : (typeof scwin['dts_Status_onfail'] === 'function') ? scwin['dts_Status_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_Status_onloadcompleted'] === 'function') ? scwin['dts_Status_onloadcompleted'] : ((typeof scwin['dts_Status_onsuccess'] === 'function') ? scwin['dts_Status_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_Status'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf30012.tx_script_dts_Status" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_script_dts_Charge2_Info
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
