/**
 * @method
 * @name scwin.getParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getParam = function () {
    /* sdd-asis-lifecycle:begin fn_getParam — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const parentWin = $c.frame.Provider("../");
    const src = $c.util.getParameter($c.frame.srcUrl, "src");
    if (src === "JSP") {
        const cmd = $c.util.getParameter($c.frame.srcUrl, "cmd");
        if (cmd === "C") {
            scwin.fn_SetCode();
            if ($c.session.getUserInfo("bondYn") === 'Y') {
                rd_rdo_SCHDL_TP_CD.Enable = false;
            }
            $c.fil.setObjectValue(rd_rdo_SCHDL_TP_CD, '5');
        } else {
            rd_rdo_SCHDL_TP_CD.Enable = false;
            const vDiscls_schdl_adm_dd = $c.util.getParameter($c.frame.srcUrl, "discls_schdl_adm_dd");
            const vBydd_seq = $c.util.getParameter($c.frame.srcUrl, "bydd_seq");
            const vInteg_usr_id = $c.util.getParameter($c.frame.srcUrl, "integ_usr_id");
            $c.fil.setObjectValue(ipt_txb_DISCLS_SCHDL_ADM_DD, vDiscls_schdl_adm_dd);
            $c.fil.setObjectValue(ipt_txb_BYDD_SEQ, vBydd_seq);
            $c.fil.setObjectValue(ipt_txb_INTEG_USR_ID, vInteg_usr_id);
            $c.fil.showObj(scwin.btn_VIEWDSCL, true);
            scwin.fn_readSchedule();
        }
    } else {
        const paramObj = parentWin.gParamObj;
        $c.fil.setObjectValue(ipt_txb_DISCLS_SCHDL_ADM_DD, paramObj.param1);
        $c.fil.setObjectValue(ipt_txb_BYDD_SEQ, paramObj.param2);
        $c.fil.setObjectValue(ipt_txb_INTEG_USR_ID, paramObj.param3);
        if (paramObj.param0 == null || paramObj.param0 == null || paramObj.param0 === "" || paramObj.param0 === "C") {
            scwin.fn_SetCode();
            $c.fil.setObjectValue(rd_rdo_SCHDL_TP_CD, '5');
        } else {
            if (paramObj.param0 === "R") {
                rd_rdo_SCHDL_TP_CD.Enable = false;
                $c.fil.showObj(scwin.btn_VIEWDSCL, true);
                scwin.fn_readSchedule();
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


