/**
 * @method
 * @name scwin.checkForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkForm = async function () {
    /* sdd-asis-lifecycle:begin fn_CheckForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (cal_txb_ADM_DEADLINE_DD.text === "") {
        await $c.win.alert("[메모일정]을 선택하세요.");
        $c.util.getComponent("cal_txb_ADM_DEADLINE_DD").focus();
        return false;
    }
    if ($c.fil.getObjectValue(ipt_txb_DISCLS_SCHDL_ADM_CONTN) === "") {
        await $c.win.alert("[메모내용]을 입력하세요.");
        $c.util.getComponent("ipt_txb_DISCLS_SCHDL_ADM_CONTN").focus();
        return false;
    }
    if ($c.fil.getObjectValue(slc_cmb_Status) === "") {
        await $c.win.alert("[일정상태]을 선택하세요.");
        $c.util.getComponent("slc_cmb_Status").focus();
        return false;
    }
    if (!$c.fil.checkMaxLength(ipt_txb_DISCLS_SCHDL_ADM_CONTN, 40, "메모내용")) {
        return false;
    }
    if (!$c.fil.checkMaxLength(scwin.txa_REMK, 1500, "비고")) {
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


